Ещё один мод, который, думаю, будет особенно полезным при создании релизов музыки. Для работы добавляем элемент &quot;Drag and Drop файл-лист&quot; после TXT[] и можно обычным перетягиванием загружать список файлов в textarea. Список при этом сортируется по алфавиту и от имени файлов &quot;отрезается&quot; расширение.<br />
Для установки добавьте в конце <b>styles\templates\posting_tpl.tpl</b>:<br />
<pre class="xfBb-code" data-lang="html">&lt;!--drag_drop_filelist--&gt;
&lt;style&gt;
    textarea.drag-over {
        border: dashed;
        border-radius: 5px;
    }
&lt;/style&gt;
&lt;script&gt;
    TPL.el_id = Object.assign({drag_drop_filelist: &#039;Drag and Drop файл-лист&#039;}, TPL.el_id);
    $(&#039;body&#039;)
        .on(&#039;drop&#039;, &#039;textarea&#039;, e =&gt; {
            if ($(e.target).parent().has(&#039;.drag_drop_filelist&#039;).length) {
                e.preventDefault();
                let files = e.originalEvent.target.files || e.originalEvent.dataTransfer.files;
                $(e.target).val($.map(files, (file)=&gt;{return file.name.replace(/\.[^/.]+$/, &quot;&quot;)}).sort().join(&#039;\r\n&#039;));
            }
            $(e.target).removeClass(&#039;drag-over&#039;);
        })
        .on(&#039;dragover&#039;, &#039;textarea&#039;, e =&gt; {
            if ($(e.target).parent().has(&#039;.drag_drop_filelist&#039;).length) {
                e.preventDefault();
                $(e.target).addClass(&#039;drag-over&#039;);
            }
        })
        .on(&#039;dragleave&#039;, &#039;textarea&#039;, e =&gt; {
            $(e.target).removeClass(&#039;drag-over&#039;);
        });
&lt;/script&gt;
&lt;div id=&quot;drag_drop_filelist&quot; style=&quot;display: none&quot;&gt;
    &lt;div class=&quot;drag_drop_filelist&quot;&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;!--/drag_drop_filelist--&gt;</pre>Пример работы:<br />
